definition.script:
pipeline {
    agent any

    stages {

        stage('Start Dictionary Container') {
            steps {
                build job: 'Dictionary ETL - Start Docker Container', parameters: [
                                        string(name: 'git_hash', value: 'ALS-10153')
                                    ]
            }
        }
        stage('Remove Old Study Data') {
            steps {
               withAWS(role:'dbgap-etl', roleAccount:'736265540791', duration: 3600, roleSessionName: 'dictionary-pipeline') {
                    s3Download(file:'Managed_Inputs.csv', bucket:'avillach-73-bdcatalyst-etl', path:'general/resources/Managed_Inputs.csv', force:true)
                }

                script {
                    def inputs = readCSV file: 'Managed_Inputs.csv', format: CSVFormat.DEFAULT.withHeader()
                    def inputCount = 0
                    inputs.each() {
                        inputCount+=1
                        if  (it['Data is ready to process'] == 'Yes' && it['Data Processed'] == 'No') {
                            build job: 'Dictionary ETL - Delete Dataset',
                                parameters: [
                                    string(name: 'dataset_ref', value: it['Study Identifier'])
                                ]
                        }
                    }
                }

            }
        }
        stage('Build Ingest CSVs from HPDS and Ingest to DB') {
            steps {
                withAWS(role:'dbgap-etl', roleAccount:'736265540791', duration: 3600, roleSessionName: 'dictionary-pipeline') {
                    s3Download(file:'Managed_Inputs.csv', bucket:'avillach-73-bdcatalyst-etl', path:'general/resources/Managed_Inputs.csv', force:true)
                }

                script {
                    def inputs = readCSV file: 'Managed_Inputs.csv', format: CSVFormat.DEFAULT.withHeader()
                    def ingestRuns = [:]
                    def inputCount = 0
                    def hrmnUpdated = false
                    build job: 'Dictionary ETL - Build Ingest Files From ColumnMeta - Loading - Concepts',
                      parameters: [
                        string(name: 'api', value: 'http://172.20.0.2:8086/')
                      ]

                    inputs.each() {  
                        inputCount+=1  
                        if  (it['Data is ready to process'] == 'Yes' && it['Data Processed'] == 'No') {  
                            if (it['DCC Harmonized'] == 'Yes') {  
                                hrmnUpdated = true  
                            }  

                            ingestRuns["updateRuns${inputCount}"] = {  

                                build job: 'Dictionary ETL - Build Ingest Files From ColumnMeta - Loading',  
                                    parameters: [  
                                        string(name: 'api', value: 'http://172.20.0.2:8086/api'),  
                                        string(name: 'datasetRef', value: it['Study Identifier'])  
                                    ]  
                            }
                        }  
                    }  
                    parallel ingestRuns

                    if (hrmnUpdated == true) {
                        echo 'At least one updated study is harmonized - triggering refresh of DCC Harmonized Dictionary'
                        build job: 'Dictionary ETL - Update DCC Harmonized Dictionary'
                    }
                }

            }
        }
        stage('Update Dictionaries from Curated JSONs') {
            steps {
                withAWS(role:'dbgap-etl', roleAccount:'736265540791', duration: 3600, roleSessionName: 'dictionary-pipeline') {
                    s3Download(file:'Managed_Inputs.csv', bucket:'avillach-73-bdcatalyst-etl', path:'general/resources/Managed_Inputs.csv', force:true)
                }

                script {
                    def inputs = readCSV file: 'Managed_Inputs.csv', format: CSVFormat.DEFAULT.withHeader()
                    def updateRuns = [:]
                    def inputCount = 0
                    inputs.each() {
                        inputCount+=1
                        if  (it['Data is ready to process'] == 'Yes' && it['Data Processed'] == 'No') {
                            echo 'Updating db for ' + it['Study Identifier']
                            if(it['Use Manual Table Methods'] == 'Yes'){
                             updateRuns["updateRuns${inputCount}"] = {
                                build job: 'Dictionary ETL - Curated metadata.json to dictionary db', propagate:true,
                                    parameters: [
                                        string(name: 'api', value: 'http://172.20.0.2:8086/api'),
                                        string(name: 'stdy_id', value: it['Study Identifier']),
                                        string(name: 'abv', value: it['Study Abbreviated Name']),
                                        [$class: 'BooleanParameterValue', name: 'hasJsonConceptPaths', value:true]
                                    ]
                                }
                            }
                            else{
                                updateRuns["updateRuns${inputCount}"] = {
                                build job: 'Dictionary ETL - Curated metadata.json to dictionary db', propagate:true,
                                    parameters: [
                                        string(name: 'api', value: 'http://172.20.0.2:8086/api'),
                                        string(name: 'stdy_id', value: it['Study Identifier']),
                                        string(name: 'abv', value: it['Study Abbreviated Name']),
                                        [$class: 'BooleanParameterValue', name: 'hasJsonConceptPaths', value:false]
                                    ]
                                }
                            }
                        }
                    }
                    parallel updateRuns
                }

            }
        }
        stage('Get updated study counts from hpds') {
            steps {
                script {
                    build job: 'Dictionary ETL - Update Meta Counts For All Consents'
                }
            }
        }
        stage('Refresh Stigvars on DB'){
            steps {
                script {
                    build job: 'Dictionary ETL - Stigvar Loader'
                }
            }
        }
        stage('Update study info from FHIR'){
            steps {
                script {
                    build job: 'Dictionary ETL - FHIR ( NIH ) Ingest'
                }
            }
        }
        stage('Update General Facets'){
            steps{
                script {
                    build job: 'Dictionary ETL - Refresh General Facets'
                }
            }
        }
        stage('Update Genomic Counts'){
        steps {
                script {
                    build propagate: false, job: 'ETL - Fetch Genomic Counts from DBGap'
                }
            }
        }
        stage('Create Files For Stigvar Identification') {
            steps {
                withAWS(role:'dbgap-etl', roleAccount:'736265540791', duration: 3600, roleSessionName: 'dictionary-pipeline') {
                    s3Download(file:'Managed_Inputs.csv', bucket:'avillach-73-bdcatalyst-etl', path:'general/resources/Managed_Inputs.csv', force:true)
                }

                script {
                    def inputs = readCSV file: 'Managed_Inputs.csv', format: CSVFormat.DEFAULT.withHeader()
                    def fileGenRuns = [:]
                    def inputCount = 0
                    inputs.each() {
                        inputCount+=1
                        if  (it['Data is ready to process'] == 'Yes' && it['Data Processed'] == 'No') {
                            echo 'Building dictionary job config for ' + it['Study Identifier']
                             fileGenRuns["fileGenRuns${inputCount}"] = {
                                build job: 'Dictionary ETL - Create Files For Stigvar Identification',
                                    parameters: [
                                        string(name: 'api', value: 'http://172.20.0.2:8086/api'),
                                        string(name: 'datasetId', value: it['Study Identifier'])
                                    ]
                             }
                        }
                    }
                    parallel fileGenRuns
                }

            }
        }
        stage('Build PGDump Tar File'){
            steps {
                script {
                    build job: 'Dictionary ETL - Export DB'

                }
                copyArtifacts(projectName: 'Dictionary ETL - Export DB');
            }
        }
    }
    post{
        success {
            archiveArtifacts artifacts: 'db_dump_name.txt', followSymlinks: false;
        }
    }
}
